// Open the fixture generated by render-product-preview.php, then run:
// playwright-cli run-code --filename tests/Browser/admin-product-preview.js
(async (page) => {
    const results = [];
    for (const viewport of [{ width: 1920, height: 960 }, { width: 1366, height: 768 }, { width: 390, height: 844 }]) {
        await page.setViewportSize(viewport);
        await page.reload();
        await page.locator('[data-preview-image]').evaluate(image => image.decode());
        const result = await page.evaluate(() => {
            const preview = document.querySelector('[data-product-preview]');
            const media = preview.querySelector('[data-preview-media]').getBoundingClientRect();
            const image = preview.querySelector('[data-preview-image]').getBoundingClientRect();
            const heading = preview.querySelector('[data-preview-heading]').getBoundingClientRect();
            const sections = [...preview.querySelectorAll(':scope > section')];
            let previousBottom = heading.bottom;
            const sectionsOverlap = sections.some(section => {
                const bounds = section.getBoundingClientRect();
                const overlap = bounds.top < previousBottom;
                previousBottom = bounds.bottom;
                return overlap;
            });
            return {
                mediaHeight: media.height,
                mediaWidth: media.width,
                overlaps: image.bottom > heading.top || sectionsOverlap,
                contained: image.top >= media.top && image.bottom <= media.bottom + 1,
                fit: getComputedStyle(preview.querySelector('[data-preview-image]')).objectFit,
                scrolls: preview.scrollHeight > preview.clientHeight,
            };
        });
        if (result.overlaps || !result.contained || Math.abs(result.mediaHeight - result.mediaWidth) > 1) {
            throw new Error(`Image overlaps preview content at ${viewport.width}x${viewport.height}: ${JSON.stringify(result)}`);
        }
        if (result.fit !== 'contain') throw new Error('Preview must show the whole product image');
        if (viewport.width > 1000 && !result.scrolls) throw new Error('Long desktop previews must scroll');

        const hidden = await page.evaluate(() => {
            const preview = document.querySelector('[data-product-preview]');
            const media = preview.querySelector('[data-preview-media]');
            const story = preview.querySelector('[data-preview-story]');
            media.hidden = true;
            story.hidden = true;
            const absent = [media, story].every(element => element.getBoundingClientRect().height === 0);
            media.hidden = false;
            story.hidden = false;
            return absent;
        });
        if (!hidden) throw new Error('Empty image and story must not occupy preview space');
        results.push({ viewport, ...result, hidden });
    }
    return results;
})
